mapper.update:
UPDATE email_notifications SET submit_attempts=submit_attempts+1,
version=version+1,updated_at=#{now} WHERE id=#{e.id} AND lease_token=#{e.leaseToken}
AND lease_until > #{now} AND remote_mail_id IS NULL

UPDATE email_notifications SET task_status=#{taskStatus},submit_attempts=#{submitAttempts},
lease_owner=#{leaseOwner},lease_token=#{leaseToken},lease_until=#{leaseUntil},
version=version+1,updated_at=#{updatedAt} WHERE id=#{id}

UPDATE email_notifications SET task_status=#{e.taskStatus},remote_mail_id=#{e.remoteMailId},
remote_status=#{e.remoteStatus},remote_attempts=#{e.remoteAttempts},accepted_at=#{e.acceptedAt},
sent_at=#{e.sentAt},poll_failures=#{e.pollFailures},last_error_code=#{e.lastErrorCode},
last_error_message=#{e.lastErrorMessage},next_run_at=#{e.nextRunAt},
lease_owner=NULL,lease_token=NULL,lease_until=NULL,version=version+1,updated_at=#{now}
WHERE id=#{e.id} AND lease_token=#{e.leaseToken} AND lease_until > #{now}
